"""
Shared pytest fixtures.

Run from the project folder:
    uv run pytest -v
"""
import shutil
import subprocess

import pytest

import timelapse_editor as te

FFMPEG_OK = bool(shutil.which("ffmpeg") and shutil.which("ffprobe"))
requires_ffmpeg = pytest.mark.skipif(not FFMPEG_OK, reason="needs ffmpeg and ffprobe on PATH")


def run_ffmpeg(args):
    subprocess.run(["ffmpeg", "-v", "error", "-y", *args], check=True)


@pytest.fixture(scope="session")
def clips(tmp_path_factory):
    """Test clips generated by ffmpeg.

    - av:    12 s, 640x360, 30 fps. Audio only between 4 s and 6 s (a tone); the rest is silence.
             Used for speech detection, automatic gain and export with sound.
    - mute:  4 s, 320x240, 30 fps, no audio.
    - long:  8 min, 160x90, 5 fps, with a constant tone. Used for the waveform at high zoom.
    """
    if not FFMPEG_OK:
        pytest.skip("needs ffmpeg and ffprobe on PATH")
    d = tmp_path_factory.mktemp("clips")
    paths = {"av": str(d / "test_clip.mp4"), "mute": str(d / "clip_no_audio.mp4"),
             "long": str(d / "clip_long.mp4")}
    bursts = "aevalsrc=exprs=if(between(t\\,4\\,6)\\,0.5*sin(2*PI*440*t)\\,0):s=48000"
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc2=size=640x360:rate=30",
                "-f", "lavfi", "-i", bursts, "-t", "12",
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-shortest", paths["av"]])
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc2=size=320x240:rate=30", "-t", "4",
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
                "-an", paths["mute"]])
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc2=size=160x90:rate=5", "-t", "480",
                "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000",
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-shortest", paths["long"]])
    return paths


@pytest.fixture
def clean_state(monkeypatch, tmp_path):
    """Isolates the server's global state: each test starts without a video and with its own cache."""
    cache = tmp_path / "cache"
    cache.mkdir()
    monkeypatch.setitem(te.STATE, "info", None)
    monkeypatch.setitem(te.STATE, "cache", str(cache))
    monkeypatch.setitem(te.STATE, "thumbs_ready", False)
    yield te.STATE


@pytest.fixture
def loaded(clean_state, clips):
    """12 s video loaded in the server (as when opening with the program)."""
    info = te.probe(clips["av"])
    clean_state["info"] = info
    return info


@pytest.fixture(scope="session", autouse=True)
def _remove_preview_folders():
    """Tests that load a video inside the test process do not run the editor's exit cleanup:
    the temporary folder of the last video is removed here."""
    yield
    tmp = te.STATE.get("tmp")
    if tmp:
        shutil.rmtree(tmp, ignore_errors=True)
